INSERT INTO categories (category_id, name, slug, description, is_active) VALUES
(1, 'เทคโนโลยีและการเขียนโปรแกรม', 'tech', 'หนังสือเรียนรู้ Coding, ฐานข้อมูล, AI และระบบคลาวด์', 1),
(2, 'ธุรกิจและการลงทุน', 'business', 'กลยุทธ์การตลาด การบริหารการเงิน และโมเดลธุรกิจสตาร์ทอัพ', 1),
(3, 'การพัฒนาตนเองและจิตวิทยา', 'self-dev', 'เพิ่มประสิทธิภาพการทำงาน จิตวิทยาการสื่อสาร และการจัดการอารมณ์', 1),
(4, 'นิยายและวรรณกรรมสร้างสรรค์', 'fiction', 'นิยายสืบสวน ไซไฟแฟนตาซี และวรรณกรรมแปลชั้นนำ', 1),
(5, 'ภาษาและการสื่อสารสากล', 'language', 'คู่มือพัฒนาทักษะภาษาอังกฤษ จีน และเทคนิคการสอบวัดระดับ', 1);
INSERT INTO authors (author_id, name, bio, email) VALUES
(1, 'ดร. สมเกียรติ์ ปัญญาดิลก', 'ผู้เชี่ยวชาญด้านวิทยาการข้อมูลและสถาปัตยกรรมระบบฐานข้อมูลขนาดใหญ่', 'somkiat.p@ai-data.org'),
(2, 'ณัฐวุฒิ นวการค้า', 'ที่ปรึกษาธุรกิจสตาร์ทอัพและวิทยากรด้านกลยุทธ์ดิจิทัลเทรนด์ใหม่', 'nattawut@startup-pro.biz'),
(3, 'พญ. ชิดชนก สุขสราญ', 'แพทย์ผู้เชี่ยวชาญด้านสุขภาพจิตและนักเขียนด้านจิตวิทยาประยุกต์เพื่อชีวิตที่สมดุล', 'chidchanok@mindfuldoc.th'),
(4, 'วายุ อักษรศิลป์', 'นักเขียนนวนิยายแนววิทยาศาสตร์แฟนตาซีและสืบสวนสอบสวน เจ้าของผลงานติดอันดับเบสต์เซลเลอร์', 'wayu@novelist-club.com'),
(5, 'เจเรมี เฉิน (Jeremy Chen)', 'อาจารย์ภาษาศาสตร์ประยุกต์และผู้เชี่ยวชาญการสอนภาษาเพื่อการสื่อสารธุรกิจระดับนานาชาติ', 'jchen@global-lang.edu'),
(6, 'กิตติศักดิ์ พัฒนาซอฟต์', 'Full-stack Architect และที่ปรึกษาด้านความปลอดภัยบนคลาวด์และ Web API', 'kittisak@devcraft.io');
INSERT INTO ebooks (ebook_id, category_id, author_id, title, isbn, description, price, cover_image, sample_file_url, full_file_url, is_published, created_at) VALUES
(1, 1, 1, 'คู่มือออกแบบและจัดการฐานข้อมูลขั้นสูง (Modern Database Design)', '978-616-01-0001-1', 'เจาะลึกการออกแบบ ERD, Normalization 3NF, BCNF, การปรับแต่ง Index และคำสั่ง SQL ประสิทธิภาพสูงสำหรับการทำงานระดับมืออาชีพ', 350.00, '/assets/covers/book1.svg', '/samples/sample_db.pdf', '/downloads/full_db_guide.pdf', 1, '2026-06-01 10:00:00'),
(2, 1, 6, 'Full-Stack JavaScript กับ Node.js & SQLite', '978-616-01-0002-8', 'สร้างเว็บแอปพลิเคชันอย่างเป็นระบบตั้งแต่พื้นฐาน REST API, จัดการฐานข้อมูล SQLite จนถึงการควบคุมสิทธิ์ความปลอดภัย', 290.00, '/assets/covers/book2.svg', '/samples/sample_js.pdf', '/downloads/full_js_stack.pdf', 1, '2026-06-02 11:00:00'),
(3, 1, 1, 'ปัญญาประดิษฐ์และ Machine Learning ฉบับใช้งานได้จริง', '978-616-01-0003-5', 'เรียนรู้หลักการ AI สมัยใหม่ การสร้างโมเดล Machine Learning และการประยุกต์ใช้งานวิเคราะห์ข้อมูลเชิงลึกในองค์กร', 420.00, '/assets/covers/book3.svg', '/samples/sample_ai.pdf', '/downloads/full_ai_practical.pdf', 1, '2026-06-03 14:00:00'),
(4, 2, 2, 'สตาร์ทอัพติดสปีด: กลยุทธ์เติบโตแบบก้าวกระโดด (Lean Startup Scale)', '978-616-02-0004-2', 'เคล็ดลับสร้างธุรกิจให้อยู่รอดและเติบโตในยุคดิจิทัล การวิเคราะห์โมเดลธุรกิจ การหา Product-Market Fit และระดมทุน', 250.00, '/assets/covers/book4.svg', '/samples/sample_startup.pdf', '/downloads/full_startup_scale.pdf', 1, '2026-06-04 09:30:00'),
(5, 2, 2, 'การเงินและการลงทุนฉบับเข้าใจง่ายสำหรับคนทำงาน', '978-616-02-0005-9', 'คู่มือวางแผนทางการเงิน การจัดพอร์ตโฟลิโอหุ้น กองทุนรวม อสังหาริมทรัพย์ และการบริหารกระแสเงินสดส่วนบุคคล', 220.00, '/assets/covers/book5.svg', '/samples/sample_finance.pdf', '/downloads/full_personal_finance.pdf', 1, '2026-06-05 13:15:00'),
(6, 3, 3, 'จัดระเบียบความคิด พิชิตความกังวล (Mindset for Success)', '978-616-03-0006-6', 'เทคนิคทางจิตวิทยาเพื่อการปรับปรุงกรอบความคิด ขจัดความเครียด เพิ่มสมาธิและประสิทธิภาพในการเรียนและการทำงานประจำวัน', 195.00, '/assets/covers/book6.svg', '/samples/sample_mindset.pdf', '/downloads/full_mindset_success.pdf', 1, '2026-06-06 15:45:00'),
(7, 3, 3, 'ศิลปะการสื่อสารและโน้มน้าวใจในที่ทำงาน', '978-616-03-0007-3', 'พัฒนาทักษะการฟัง การเจรจาต่อรอง และการนำเสนองานเพื่อสร้างความสัมพันธ์ที่ดีและบรรลุเป้าหมายในอาชีพการงาน', 210.00, '/assets/covers/book7.svg', '/samples/sample_comm.pdf', '/downloads/full_effective_comm.pdf', 1, '2026-06-07 10:20:00'),
(8, 4, 4, 'รหัสลับนครสูญหาย (The Lost Chrono Cipher)', '978-616-04-0008-0', 'นิยายไซไฟสืบสวนระทึกขวัญ การไขปริศนาโบราณคดีไซเบอร์และการผจญภัยข้ามมิติเวลาที่หยุดไม่อยู่', 280.00, '/assets/covers/book8.svg', '/samples/sample_chrono.pdf', '/downloads/full_lost_chrono.pdf', 1, '2026-06-08 16:30:00'),
(9, 4, 4, 'เงาอัศวินแห่งรัตติกาล (Shadow of the Knight)', '978-616-04-0009-7', 'มหากาพย์วรรณกรรมแฟนตาซี การต่อสู้เพื่อความยุติธรรม เวทมนตร์ และมิตรภาพที่ต้องแลกมาด้วยความเสียสละ', 260.00, '/assets/covers/book9.svg', '/samples/sample_shadow.pdf', '/downloads/full_shadow_knight.pdf', 1, '2026-06-09 11:10:00'),
(10, 5, 5, 'พิชิตข้อสอบภาษาอังกฤษเพื่อการทำงาน (Business English Mastery)', '978-616-05-0010-3', 'คำศัพท์ สำนวน การเขียนอีเมลธุรกิจ การประชุม และเทคนิคการทำข้อสอบ TOEIC ให้ได้คะแนน 850+', 270.00, '/assets/covers/book10.svg', '/samples/sample_eng.pdf', '/downloads/full_business_eng.pdf', 1, '2026-06-10 14:00:00'),
(11, 5, 5, 'ภาษาญี่ปุ่นระดับต้นเพื่อการท่องเที่ยวและการทำงาน', '978-616-05-0011-0', 'ไวยากรณ์และบทสนทนาภาษาญี่ปุ่นที่จำเป็นในชีวิตประจำวัน พร้อมแบบฝึกหัดเตรียมสอบ JLPT N5-N4', 240.00, '/assets/covers/book11.svg', '/samples/sample_jp.pdf', '/downloads/full_basic_japanese.pdf', 1, '2026-06-11 09:00:00'),
(12, 1, 6, 'Cloud Security & DevOps Fundamentals', '978-616-01-0012-7', 'แนวทางปฏิบัติในการดูแลความปลอดภัยของระบบคลาวด์ คอนเทนเนอร์ Docker, Kubernetes และ CI/CD Pipeline', 380.00, '/assets/covers/book12.svg', '/samples/sample_devops.pdf', '/downloads/full_cloud_devops.pdf', 1, '2026-06-12 17:00:00');
